        require(amount > 0);
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 zeroBalBefore = c.balanceOf(address(0)); if (__ESBMC_reverted()) return;
        c.mintToken(address(0), amount); if (__ESBMC_reverted()) return;
