// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 amount) internal {
        vm.assume(amount > 0);
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 zeroBalBefore;
        try c.balanceOf(address(0)) returns (uint256 __r) { zeroBalBefore = __r; } catch { return; }
        try c.mintToken(address(0), amount) {} catch { return; }
        assertTrue(c.totalSupply() == supplyBefore + amount && c.balanceOf(address(0)) == zeroBalBefore + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
